import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testFilterAbove50() {
        Assert.assertEquals(listOf(72, 91), filterAbove(listOf(45, 72, 38, 91), 50))
    }

    @Test
    fun testNoneAbove() {
        Assert.assertEquals(emptyList<Int>(), filterAbove(listOf(10, 20, 30), 100))
    }

    @Test
    fun testAllAbove() {
        Assert.assertEquals(listOf(80, 90, 100), filterAbove(listOf(80, 90, 100), 50))
    }
}
